// 1. Redis Lua 预扣库存：库存判断、限购判断、扣减、记录已购 —— 一个原子单元
public class SeckillService {
    private final StringRedisTemplate redis;
    private final KafkaTemplate<String, String> kafka;

    private static final String SECKILL_SCRIPT =
        "local stock = tonumber(redis.call('get', KEYS[1])) " +
        "if stock == nil or stock <= 0 then return -1 end " +
        "local bought = redis.call('sismember', KEYS[2], ARGV[1]) " +
        "if bought == 1 then return -2 end " +
        "redis.call('decr', KEYS[1]) " +
        "redis.call('sadd', KEYS[2], ARGV[1]) " +
        "return 1";

    public SeckillResult doSeckill(String activityId, String userId, String skuId) {
        String stockKey = "seckill:stock:" + activityId + ":" + skuId;
        String boughtKey = "seckill:bought:" + activityId + ":" + skuId;

        // Lua 脚本原子执行：读库存→判断→判断限购→扣减→记录已购
        Long result = redis.execute(
            new DefaultRedisScript<>(SECKILL_SCRIPT, Long.class),
            Arrays.asList(stockKey, boughtKey),
            userId
        );

        if (result == -1) return SeckillResult.SOLD_OUT;
        if (result == -2) return SeckillResult.ALREADY_BOUGHT;

        // 预扣成功 → 写入下单消息
        SeckillMessage msg = new SeckillMessage(activityId, userId, skuId);
        try {
            kafka.send("seckill-order", activityId + ":" + userId, JSON.toJSONString(msg)).get();
            return SeckillResult.ACCEPTED;
        } catch (Exception e) {
            // MQ 投递失败：必须立即回补，否则少卖
            // 生产中推荐本地 outbox 表 + 定时任务，避免 send().get() 卡住
            redis.opsForValue().increment(stockKey);
            redis.opsForSet().remove(boughtKey, userId);
            return SeckillResult.RETRY_LATER;
        }
    }
}

// 2. 异步下单消费者：幂等 + DB 条件扣减 + 唯一索引兜底
@KafkaListener(topics = "seckill-order")
@Transactional
public void handleSeckillOrder(String message) {
    SeckillMessage msg = JSON.parseObject(message, SeckillMessage.class);

    // 幂等检查：业务唯一键防重复订单
    if (orderRepository.existsByActivityIdAndUserId(msg.getActivityId(), msg.getUserId())) {
        return;
    }

    // DB 条件扣减：affected rows = 0 说明库存不足，需要补偿 Redis
    boolean deducted = inventoryMapper.deductStock(
        msg.getActivityId(), msg.getSkuId(), 1
    );
    if (!deducted) {
        compensateRedisStock(msg); // 回补 Redis 库存和已购标记
        return;
    }

    // 创建订单（DB 唯一索引 uk_activity_user 兜底防重复）
    orderService.createSeckillOrder(msg.getActivityId(), msg.getUserId(), msg.getSkuId());
}

// SQL：UPDATE inventory SET quantity = quantity - #{count}
//      WHERE activity_id = #{activityId} AND sku_id = #{skuId} AND quantity >= #{count}
// 唯一索引：ALTER TABLE seckill_order ADD UNIQUE uk_activity_user(activity_id, user_id)

// 3. 分段库存：哈希路由 + 有限重试
public class SegmentStockService {
    private static final int SEGMENT_COUNT = 16;

    public boolean deduct(String activityId, String skuId, String userId) {
        int base = Math.abs(userId.hashCode()) % SEGMENT_COUNT;
        for (int offset = 0; offset < SEGMENT_COUNT; offset++) {
            int segment = (base + offset) % SEGMENT_COUNT;
            String key = "seckill:stock:" + activityId + ":" + skuId + ":" + segment;
            Long left = redis.opsForValue().decrement(key);
            if (left != null && left >= 0) {
                return true; // 扣减成功
            }
            // 当前段已空，回补后尝试下一段
            if (left != null) {
                redis.opsForValue().increment(key);
            }
        }
        return false; // 所有段都已售罄
    }
}
